<?php
 namespace Pterodactyl\Http\Controllers\Admin\Dezerx; use Throwable; use Illuminate\Http\Request; use Illuminate\Validation\Rule; use Pterodactyl\Models\Server; use Illuminate\Http\RedirectResponse; use Prologue\Alerts\AlertsMessageBag; use Pterodactyl\Http\Controllers\Controller; use Pterodactyl\Services\Servers\SuspensionService; use Pterodactyl\Services\Servers\ServerDeletionService; use Pterodactyl\Services\Servers\ReinstallServerService; class ServerBulkController extends Controller { public const ACTIONS = [ 'suspend' => 'suspended', 'unsuspend' => 'unsuspended', 'reinstall' => 'sent to reinstall', 'delete' => 'deleted', 'force-delete' => 'force deleted', ]; private const MAX = 100; public const DELETE_WORD = 'DELETE'; public function __construct( private AlertsMessageBag $alert, private SuspensionService $suspension, private ReinstallServerService $reinstall, private ServerDeletionService $deletion, ) { } public function __invoke(Request $request): RedirectResponse { $data = $request->validate([ 'action' => ['required', 'string', Rule::in(array_keys(self::ACTIONS))], 'servers' => ['required', 'array', 'min:1', 'max:' . self::MAX], 'servers.*' => ['integer', 'min:1', 'distinct'], 'confirm' => ['nullable', 'string', 'max:20'], ]); $action = $data['action']; if (in_array($action, ['delete', 'force-delete'], true) && ($data['confirm'] ?? '') !== self::DELETE_WORD) { $this->alert->danger('Nothing was deleted: type ' . self::DELETE_WORD . ' to confirm a bulk delete.')->flash(); return $this->back($request); } $done = 0; $failed = []; foreach (Server::query()->whereIn('id', array_map('intval', $data['servers']))->get() as $server) { try { match ($action) { 'suspend' => $this->suspension->toggle($server, SuspensionService::ACTION_SUSPEND), 'unsuspend' => $this->suspension->toggle($server, SuspensionService::ACTION_UNSUSPEND), 'reinstall' => $this->reinstall->handle($server), 'delete' => $this->deletion->withForce(false)->handle($server), 'force-delete' => $this->deletion->withForce(true)->handle($server), }; ++$done; } catch (Throwable $exception) { report($exception); $failed[] = $server->name; } } if ($done > 0) { $this->alert->success($done . ' ' . ($done === 1 ? 'server' : 'servers') . ' ' . self::ACTIONS[$action] . '.')->flash(); } if ($failed !== []) { $this->alert->danger( 'Could not be ' . self::ACTIONS[$action] . ': ' . implode(', ', $failed) . '. The panel log has the reason for each.' )->flash(); } return $this->back($request); } private function back(Request $request): RedirectResponse { $query = (string) $request->input('return', ''); if (strlen($query) > 2000 || preg_match('/^\?[^\s#\\\\]*$/', $query) !== 1) { $query = ''; } return redirect()->to(route('admin.servers') . $query); } } 